head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil53000n";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil53000n.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_pubOfrSchdlAndCapMasterPage.get("total")) + "건 (" + String(dma_pubOfrSchdlAndCapMasterPage.get("currentPage")) + "/" + String(dma_pubOfrSchdlAndCapMasterPage.get("endListPage")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_openAdjReqWin();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil53000n.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pubOfrSchdlAndCapMasterPageList_oncellclick
 * @description grd_pubOfrSchdlAndCapMasterPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pubOfrSchdlAndCapMasterPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pubOfrSchdlAndCapMasterPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pubOfrSchdlAndCapMasterPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["step1DtlStat"] === '30') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; } return; } if (r["step1DtlStat"] === '') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '32') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '33') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '34') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '35') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '36') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '37') { await scwin.pubofrSchdl(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '30') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '32') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '33') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '34') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '35') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '36') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["step2DtlStat"] === '37') { await scwin.cap(r["bzProcsNo"]); return; }
        if (r["submitPossibleYn"] === 'Y') { await scwin.submit(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35') { await scwin.submit(r["bzProcsNo"]); return; }
        if (r["step1DtlStat"] === '34' || r["step2DtlStat"] === '34') { await scwin.openAdjReqPop(r["bzProcsNo"], "130"); return; }
        if (r["step1DtlStat"] === '35' || r["step2DtlStat"] === '35') { await scwin.openAdjReqPop(r["bzProcsNo"], "130"); return; }
        if (r["recvCompleteYn"] === 'Y') { await scwin.openAdjReqPop(r["bzProcsNo"], "130"); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pubOfrSchdlAndCapMasterPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_163_onclick
 * @description krxpage_pagenavigator_163 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_163_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_openAdjReqWinReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_163.page' }); } await scwin.tx_fn_openAdjReqWin(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_pubofrSchdl
 * @description pubofr Schdl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_pubofrSchdl = async function () {
    const sbmOptions = {
        id: "tx_fn_pubofrSchdl",
        method: "post",
        action: "/listInvstg/pubOfrSchdl.do",
        ref: "dma_pubofrSchdlReq",
        target: "dlt_pubOfrSchdlAndCapMasterPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_cap
 * @description cap 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_cap = async function () {
    const sbmOptions = {
        id: "tx_fn_cap",
        method: "post",
        action: "/listInvstg/cap.do",
        ref: "dma_capReq",
        target: "dlt_pubOfrSchdlAndCapMasterPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function () {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: "/listInvstg/pubOfrSchdlAndCap.do",
        ref: "dma_submitReq",
        target: "dlt_pubOfrSchdlAndCapMasterPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_openAdjReqWin
 * @description open Adj Req Win 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_openAdjReqWin = async function () {
    const sbmOptions = {
        id: "tx_fn_openAdjReqWin",
        method: "post",
        action: "/listInvstg/searchNewListInvstgMaster.do",
        ref: "dma_openAdjReqWinReq",
        target: "dlt_pubOfrSchdlAndCapMasterPageList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil53000n.tx_fn_openAdjReqWin" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_163").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/listInvstg/pubOfrSchdlAndCap.do",
        ref: "dma_searchListReq",
        target: "dlt_pubOfrSchdlAndCapMasterPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_pubofrSchdlReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_pubOfrSchdlAndCapMasterPageList_fmt_column7
 * @description grd pub Ofr Schdl And Cap Master Page List fmt column7 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pubOfrSchdlAndCapMasterPageList_fmt_column7 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pubOfrSchdlAndCapMasterPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "step1DtlStat") ?? '') : '');
        if (v === '') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "미작성" + '</a>'; }
        if (v === '30') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "작성중" + '</a>'; }
        if (v === '32') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "제출완료" + '</a>'; }
        if (v === '33') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "접수완료" + '</a>'; }
        if (v === '34') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        if (v === '35') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정가능" + '</a>'; }
        if (v === '36') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정불가" + '</a>'; }
        if (v === '37') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "재작성" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pubOfrSchdlAndCapMasterPageList.column7" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pubOfrSchdlAndCapMasterPageList_fmt_column8
 * @description grd pub Ofr Schdl And Cap Master Page List fmt column8 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pubOfrSchdlAndCapMasterPageList_fmt_column8 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pubOfrSchdlAndCapMasterPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "step2DtlStat") ?? '') : '');
        if (v === '') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "미작성" + '</a>'; }
        if (v === '30') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "작성중" + '</a>'; }
        if (v === '32') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "제출완료" + '</a>'; }
        if (v === '33') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "접수완료" + '</a>'; }
        if (v === '34') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정요청" + '</a>'; }
        if (v === '35') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "수정가능" + '</a>'; }
        if (v === '36') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + "수정불가" + '</a>'; }
        if (v === '37') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "재작성" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pubOfrSchdlAndCapMasterPageList.column8" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pubOfrSchdlAndCapMasterPageList_fmt_column9
 * @description grd pub Ofr Schdl And Cap Master Page List fmt column9 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pubOfrSchdlAndCapMasterPageList_fmt_column9 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_pubOfrSchdlAndCapMasterPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "recvCompleteYn") ?? '') : '');
        if (v === 'N') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "제출 - - 제출 - - 제출완료 -" + '</a>'; }
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + "제출 - 접수완료 수정요청 제출 수정요청 제출완료 - 접수완료 수정요청" + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_pubOfrSchdlAndCapMasterPageList.column9" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_pubOfrSchdlAndCapMasterPageList_fillAct
 * @description grd pub Ofr Schdl And Cap Master Page List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pubOfrSchdlAndCapMasterPageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_pubOfrSchdlAndCapMasterPageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["step1DtlStat"] === '30') { v = "작성중"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pubOfrSchdlAndCapMasterPageList.fillAct' });
    }
};

/**
 * @method
 * @name pubofrSchdl
 * @description pubofr Schdl 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.pubofrSchdl = async function (bzProcsNo) {
    const frm = (document.pubOfrSchdlAndCapMasterForm || { elements: [] });
    frm.action = "pubOfrSchdl.do";
    $c.util.getComponent('dma_pubofrSchdlReq').set('method', "searchPubOfrSchdl");
    $c.util.getComponent("dma_pubofrSchdlReq").set("bzProcsNo", bzProcsNo);
    const nr = await scwin.tx_fn_pubofrSchdl();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil53100/jldfil53100.xml", { "method": "searchPubOfrSchdl", "bzProcsNo": bzProcsNo });
    }
};

/**
 * @method
 * @name cap
 * @description cap 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cap = async function (bzProcsNo) {
    const frm = (document.pubOfrSchdlAndCapMasterForm || { elements: [] });
    frm.action = "cap.do";
    $c.util.getComponent('dma_pubofrSchdlReq').set('method', "searchCap");
    $c.util.getComponent("dma_pubofrSchdlReq").set("bzProcsNo", bzProcsNo);
    const nr = await scwin.tx_fn_cap();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil53200/jldfil53200.xml", { "method": "searchCap", "bzProcsNo": bzProcsNo });
    }
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} bzProcsNo bzProcsNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (bzProcsNo) {
    if (await $c.win.confirm('제출 하시겠습니까?')) {
        const frm = (document.pubOfrSchdlAndCapMasterForm || { elements: [] });
        frm.action = "pubOfrSchdlAndCap.do";
        $c.util.getComponent('dma_pubofrSchdlReq').set('method', "submitPubOfrSchdlAndCap");
        $c.util.getComponent("dma_pubofrSchdlReq").set("bzProcsNo", bzProcsNo);
        const nr = await scwin.tx_fn_submit();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil53000/jldfil53000.xml", { "method": "submitPubOfrSchdlAndCap", "bzProcsNo": bzProcsNo });
        }
    }
};

/**
 * @method
 * @name openAdjReqWin
 * @description open Adj Req Win 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqWin = async function () {
    const adjReqWin = {};
    const bzProcsNo = $c.util.getComponent('ipt_bzProcsNo').getValue();
    const listInvstgBzTpCd = $c.util.getComponent('ipt_listInvstgBzTpCd').getValue();
    const url = "/jldfil52530/jldfil52530.xml?method=selectAvailableAdjReq&bzProcsNo=" + bzProcsNo + "&listInvstgBzTpCd=" + listInvstgBzTpCd;
    const style = "dialogWidth:700px;dialogHeight:700px;scroll:no;resize:no";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
